var createdProviders []*unstructured.Unstructured
var createdSecrets []*corev1.Secret

// cloneValuesFrom clones the secret and provider referenced by a package's ValuesFrom (if any),
// appending any created objects to createdSecrets and createdProviders.
cloneValuesFrom := func(pkg *runtanzuv1alpha1.TanzuClusterBootstrapPackage) error {
	if pkg == nil || pkg.ValuesFrom == nil {
		return nil
	}
	secret, err := updateValuesFromSecret(pkg.ValuesFrom, packageShortName(pkg.RefName))
	if err != nil {
		return err
	}
	createdSecrets = append(createdSecrets, secret)

	provider, err := updateValuesFromProvider(pkg.ValuesFrom, packageShortName(pkg.RefName))
	if err != nil {
		return err
	}
	createdProviders = append(createdProviders, provider)
	return nil
}

for _, pkg := range []*runtanzuv1alpha1.TanzuClusterBootstrapPackage{
	bootstrap.Spec.CNI, bootstrap.Spec.CPI, bootstrap.Spec.CSI, bootstrap.Spec.Kapp,
} {
	if err := cloneValuesFrom(pkg); err != nil {
		return nil, nil, err
	}
}

